from launch import LaunchDescription
from launch_ros.actions import Node
from moveit_configs_utils import MoveItConfigsBuilder
from moveit_configs_utils.launches import (
    generate_move_group_launch,
    generate_static_virtual_joint_tfs_launch,
)


def generate_launch_description():
    moveit_config = (
        MoveItConfigsBuilder("simple_arm", package_name="simple_arm_moveit_config")
        .robot_description(file_path="config/simple_arm.urdf.xacro")
        .trajectory_execution(file_path="config/moveit_controllers.yaml")
        .planning_pipelines(default_planning_pipeline="ompl", pipelines=["ompl"])
        .to_moveit_configs()
    )

    ld = LaunchDescription()

    # Publish robot_state (tf) from joint_states
    ld.add_action(
        Node(
            package="robot_state_publisher",
            executable="robot_state_publisher",
            output="screen",
            parameters=[moveit_config.robot_description],
        )
    )

    # Static tf for the SRDF virtual joint (world -> base_link)
    for action in generate_static_virtual_joint_tfs_launch(moveit_config).entities:
        ld.add_action(action)

    # ros2_control_node: controller_manager driving the mock hardware
    ld.add_action(
        Node(
            package="controller_manager",
            executable="ros2_control_node",
            output="screen",
            parameters=[
                moveit_config.robot_description,
                str(moveit_config.package_path / "config" / "ros2_controllers.yaml"),
            ],
        )
    )

    # Spawn joint_state_broadcaster and the arm's trajectory controller
    for controller in ["joint_state_broadcaster", "arm_controller"]:
        ld.add_action(
            Node(
                package="controller_manager",
                executable="spawner",
                arguments=[controller],
                output="screen",
            )
        )

    # move_group itself
    for action in generate_move_group_launch(moveit_config).entities:
        ld.add_action(action)

    return ld

